 void choose(Actor actor,UUID town,String name,BuildingStyle style)throws Exception{var service=field(builds,"cityStyles");Class<?> type=Class.forName("ru.neverland.townybuilds.construction.CityStyles$View",true,builds.getClass().getClassLoader());var ctor=type.getDeclaredConstructors()[0];ctor.setAccessible(true);Object view=ctor.newInstance(actor,town,name,style);call(service,"confirm",new Class<?>[]{Player.class,type},actor,view);}
 void styles()throws Exception{
  check(Bukkit.isOwnedByCurrentRegion(mayor),"real CraftPlayer handle belongs to current Folia region");data.town(DEF).setLevel("town_hall",1);data.town(DEF).setConstructionSite(new ConstructionSite("town_hall",world.getUID(),8,150,8,BlockFace.NORTH,1,1,1,false));choose(mayor,DEF,defender.getName(),BuildingStyle.FANTASY);check(data.town(DEF).buildingStyle().equals("fantasy")&&data.town(DEF).styleChosen(),"mayor chooses future-city style once");check(data.town(DEF).constructionSite("town_hall").architectureVersion()==6,"saved existing site remains medieval");deny(()->choose(mayor,DEF,defender.getName(),BuildingStyle.MODERN),"second style choice refused");
  var before=new PreNewTownEvent(founder,"ModernCity",origin,500);Bukkit.getPluginManager().callEvent(before);check(before.isCancelled(),"Towny creation intercepted before price confirmation");choose(founder,null,"ModernCity",BuildingStyle.MODERN);check(founder.commands.contains("town new ModernCity"),"confirmed choice resumes ordinary Towny creation command");TownyUniverse.getInstance().newTownInternal("ModernCity",NEW);var town=TownyAPI.getInstance().getTown(NEW);var resident=TownyAPI.getInstance().getResident(FOUNDER);resident.setTown(town);town.setMayor(resident);town.setRegistered(System.currentTimeMillis());resident.save();town.save();Bukkit.getPluginManager().callEvent(new NewTownEvent(town));check(data.town(NEW).styleChosen()&&data.town(NEW).buildingStyle().equals("modern"),"Towny NewTownEvent applies durable style reservation");
  var generator=new BuildingBlueprintGenerator();Set<BlueprintBlock> blocks=new HashSet<>();for(var style:BuildingStyle.values())for(String project:generator.supportedProjects()){var plan=generator.generateForStyle(project,generator.maximumStage(project),style);blocks.addAll(plan.blocks().values());}var invalid=blocks.stream().map(BlueprintBlock::material).distinct().filter(m->!m.isBlock()).map(Enum::name).sorted().toList();Files.writeString(proof.resolve("invalid-blueprint-materials.txt"),invalid.toString());if(!invalid.isEmpty())throw new IllegalArgumentException("Invalid native blueprint materials: "+invalid);for(var block:blocks){org.bukkit.block.data.BlockData bd;try{bd=block.material().createBlockData();}catch(Exception ex){throw new IllegalArgumentException("Blueprint material is not a native block: "+block.material()+" role="+block.role(),ex);}var orientation=ConstructionService.class.getDeclaredMethod("orientExpectedState",org.bukkit.block.data.BlockData.class,BlueprintBlock.class,ConstructionSite.class);orientation.setAccessible(true);orientation.invoke(null,bd,block,new ConstructionSite("town_hall",world.getUID(),0,150,0,BlockFace.EAST,0,1,1,true));Bukkit.createBlockData(bd.getAsString());}check(blocks.size()>50,"all themed BlockData families and orientations accepted by actual Folia");
  data.town(NEW).setLevel("forge",2);data.town(NEW).setConstructionSite(new ConstructionSite("forge",world.getUID(),0,150,0,BlockFace.NORTH,2,2,1,false,1006));var plans=Bukkit.getServicesManager().load(BuildingRepairPlansApi.class);var repair=plans.plan(NEW,"forge");check(!((List<?>)repair.get("cells")).isEmpty(),"modern completed building has native repair plan");boolean mapped=((List<Map<String,Object>>)repair.get("cells")).stream().anyMatch(c->!c.get("baseMaterial").equals(c.get("material")));check(mapped,"repair geometry carries base HP material alongside actual theme");var parsed=new RepairPlans().plan(NEW,"forge");check(parsed.cells().stream().allMatch(cell->!cell.hpMaterial().isBlank()),"all repair targets retain balance material");data.markDirty();data.saveOrThrow();
 }
 void materials()throws Exception{
  var materials=Bukkit.getServicesManager().load(BuildingMaterialsApi.class);var needs=materials.needs(DEF,"forge");List<Map<String,Object>> missing=(List<Map<String,Object>>)needs.get("materials");check(!missing.isEmpty(),"native materials API computes actual next-level deficit");for(var entry:missing){var sample=ContractCodec.item((String)entry.get("item"));check(sample.getAmount()==1,"large requirement serializes only a legal one-item sample");}
  var first=missing.getFirst();ItemStack sample=ContractCodec.item((String)first.get("item"));int required=((Number)first.get("amount")).intValue();var stock=new ItemStack[54];stock[0]=sample.clone();stock[0].setAmount(Math.min(10,required));data.town(DEF).setStorage(stock,54);data.markDirty();data.saveOrThrow();var current=materials.needs(DEF,"forge");check(!needs.get("fingerprint").equals(current.get("fingerprint")),"warehouse change invalidates city-order quote");
  var controller=new BuildOrders((org.bukkit.plugin.java.JavaPlugin)Bukkit.getPluginManager().getPlugin("NeverLandTownyContracts"),new ru.neverland.mintcontracts.integration.TownyHook((org.bukkit.plugin.java.JavaPlugin)Bukkit.getPluginManager().getPlugin("NeverLandTownyContracts")),contracts);Object quote=call(controller,"quote",new Class<?>[]{Map.class,Map.class},needs,first);var method=quote.getClass().getDeclaredMethod("definition");method.setAccessible(true);ContractDefinition definition=(ContractDefinition)method.invoke(quote);long before=Math.round(defender.getAccount().getHoldingBalance()*100);check(contracts.activate(defender,definition)==ContractService.ActivateResult.SUCCESS,"material order uses real municipal escrow");check(Math.round(defender.getAccount().getHoldingBalance()*100)==before-Math.round(definition.reward()*100),"only city treasury funds material reward");check(contracts.activate(defender,definition)==ContractService.ActivateResult.DUPLICATE,"duplicate build-order template denied");getConfig().set("material-contract",contracts.active(DEF).getFirst().id().toString());saveConfig();
 }
 void ecology()throws Exception{call(field(Bukkit.getPluginManager().getPlugin("NeverLandTownyResources"),"service"),"refresh",new Class<?>[]{boolean.class},false);var api=Bukkit.getServicesManager().load(TownyEnvironmentApi.class);var service=Bukkit.getPluginManager().getPlugin("NeverLandTownyEnvironment");call(field(service,"service"),"refreshView",new Class<?>[]{});var forecast=api.forecast(DEF,"foundry",2,3600);check(Boolean.TRUE.equals(forecast.get("ready"))&&Boolean.TRUE.equals(forecast.get("relevant")),"native environment provider computes pre-build forecast: "+forecast);SuiteState.freeze(service.getName());try{deny(()->ApiServices.call(service.getName(),"ru.neverland.townyenvironment.api.TownyEnvironmentApi","forecast",new Class<?>[]{UUID.class,String.class,int.class,int.class},DEF,"foundry",2,3600),"paused environment cannot pretend to supply a live forecast");}finally{SuiteState.thaw(service.getName());}}
 void quests()throws Exception{var service=(QuestService)field(Bukkit.getPluginManager().getPlugin("NeverLandTownyQuests"),"service");var repo=(QuestRepository)field(service,"repository");var sanitation=service.settings().projects().get("sanitation");repo.put(DEF,new CityProject(id("complete-sanitation"),sanitation,sanitation.stages().size(),0,CityProject.Status.COMPLETED));deny(()->service.begin(mayor,"green_future"),"exclusive project branch needs explicit confirmation");service.begin(mayor,"green_future",true);service.control(DEF,"green_future","cancel");deny(()->service.begin(mayor,"industrial_future",true),"cancelled branch still excludes incompatible alternative");check(!service.branchReason(DEF,service.settings().projects().get("industrial_future")).isEmpty(),"native branch history supplies readable exclusion reason");}
