 void restartChecks050()throws Exception{check(data.town(DEF).buildingStyle().equals("fantasy")&&data.town(NEW).buildingStyle().equals("modern"),"city styles survive native full restart");check(data.town(DEF).constructionSite("town_hall").architectureVersion()==6&&data.town(NEW).constructionSite("forge").architectureVersion()==1006,"old and themed site identities both preserved");check(companies.ledger.company(COMPANY).balance()==9755,"salary payments not repeated at startup");check(companies.ledger.state().payments().get(WAGE).phase()==CompanyData.Phase.DONE,"completed salary receipt restored");check(plugin.hours().describe(DEF).contains("18:00"),"announced vulnerability schedule survives restart");check(StockMath.count(plugin.supplies().stock(DEF),new ItemStack(Material.BREAD))==10,"camp reserves survive restart independently of camp lifetime");check(plugin.supplies().received(DEF,SHIP,CAMP,new ItemStack[]{new ItemStack(Material.BREAD,10)}),"old destination delivery receipt restored");var service=(QuestService)field(Bukkit.getPluginManager().getPlugin("NeverLandTownyQuests"),"service");deny(()->service.begin(mayor,"industrial_future",true),"restart never resets cancelled branch selection");UUID contract=UUID.fromString(getConfig().getString("material-contract"));check(contracts.find(DEF,contract.toString())!=null,"funded dynamic construction order snapshot survives restart");complete();}
